class Solution:
    def removeDuplicates(self, s: str, k: int) -> str:
        changed = True
        while changed:
            changed = False
            i = 0
            parts = []
            while i < len(s):
                j = i
                while j < len(s) and s[j] == s[i]:
                    j += 1
                count = j - i
                if not changed and count >= k:
                    keep = count % k
                    parts.append(s[i] * keep)
                    changed = True
                else:
                    parts.append(s[i:j])
                i = j
            s = "".join(parts)
        return s

solutions.better:
class Solution:
    def removeDuplicates(self, s: str, k: int) -> str:
        stack = []
        for ch in s:
            if stack and stack[-1][0] == ch:
                stack[-1][1] += 1
                if stack[-1][1] == k:
                    stack.pop()
            else:
                stack.append([ch, 1])
        return "".join(ch * count for ch, count in stack)

