class Solution:
    def removeDuplicates(self, s: str, k: int) -> str:
        chars = []
        counts = []
        for ch in s:
            chars.append(ch)
            if len(chars) > 1 and chars[-2] == ch:
                counts.append(counts[-1] + 1)
            else:
                counts.append(1)
            if counts[-1] == k:
                del chars[-k:]
                del counts[-k:]
        return "".join(chars)

